            Table = this.Module.tblList;
            Row = Table instanceof tp.DataTable && !tp.IsEmpty(Id) ? Table.FindRow(Table.KeyField, Id) : null;
            if (Row instanceof tp.DataRow)
                return Row;
            Row = this.Module.Row;
