        /**
         * Created data sources keyed by table name.
         * @type {object}
         */
        this.SourceByTable = {};
        /**
         * Created lookup list data sources keyed by lookup source name.
         * @type {object}
         */
        this.ListSourceByName = {};
        /**
         * Created detail grids.
         * @type {tp.Grid[]}
         */
        this.DetailGrids = [];
        /**
         * The root tab control.
         * @type {tp.TabControl|null}
         */
